local entries = WordHunterWoW_EntityDataBySource["multilanguage-classic"].kinds["spell"]["deDE"]
entries[415817] = { ["name"] = "Schneller Tod", ["text"] = "Erhaltet die Fähigkeit 'Schneller Tod':\n\nVerringert die Abklingzeit von 'Schnellfeuer' um 80%, 'Schnellfeuer' erhöht zusätzlich das Nahkampfangriffstempo um 40% und Eure nächste Schussfähigkeit innerhalb von 20 Sek., nachdem Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, verursacht 20% mehr Schaden." }
entries[415818] = { ["name"] = "Scharfschützentraining", ["text"] = "Erhaltet die Fähigkeit 'Scharfschützentraining':\n\nDie kritische Trefferchance Eurer Schussfähigkeiten ist um 2% erhöht, wenn Ihr Euch in den letzten 2 Sek. nicht bewegt habt. Dieser Effekt stapelt sich pro Sekunde bis auf maximal 5 Stapel. Bei 2 oder mehr Stapeln kann 'Gezielter Schuss' sofort eingesetzt werden. Während Ihr Euch bewegt, verliert Ihr 1 Stapel pro Sekunde." }
entries[415822] = { ["name"] = "Raptorenfuror", ["text"] = "Erhaltet die Fähigkeit 'Raptorenfuror':\n\nEuer 'Raptorstoß' erhöht den durch 'Raptorstoß' und 'Mungobiss' verursachten Schaden 30 Sek. lang um 15%. Bis zu 5-mal stapelbar. Nachfolgende Einsätze verlängern nicht die Dauer des Effekts." }
entries[415918] = { ["name"] = "Umhang prägen - Blutroter Sturm", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang" }
entries[415922] = { ["name"] = "Umhang prägen - Donnerbüchse", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang\nPrägt Euren Umhang mit der Rune 'Donnerbüchse':\n\nFeuert einen Musketenschuss auf bis zu 4 Gegner und verursacht in einem kegelförmigen Bereich vor dem Schurken [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Angriffskraft] bis [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Angriffskraft] körperlichen Schaden." }
entries[415926] = { ["name"] = "Stiefel prägen - Auflauern", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Auflauern':\n\nDie Treffer Eurer Fähigkeiten 'Hinterhalt' und 'Meucheln' bringen Euer Ziel aus dem Gleichgewicht, was die Zeit zwischen seinen Nahkampfangriffen um 10% erhöht sowie seine Bewegungsgeschwindigkeit um 50% verringert. Hält 8 Sek. lang an." }
entries[415934] = { ["name"] = "Stiefel prägen - Zaubermacht", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Zaubermacht':\n\nErhöht den Schadensbonus bei kritischen Treffern aller Zauber um 50%." }
entries[415936] = { ["name"] = "Handschuhe prägen - Lebende Bombe", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe" }
entries[415939] = { ["name"] = "Hosen prägen - Rasende Regeneration", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Euren Hosen mit der Rune 'Massenregeneration':\n\nHeilt alle verbündeten Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um den anvisierten Spielercharakter im Verlauf von 3 Sek. um [Quellwert] Gesundheit und belegt jedes Ziel für 15 Sek. mit 'Zeitenleuchtfeuer'.\n\nZeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.", ["unresolvedValues"] = true }
entries[415942] = { ["name"] = "Brustteil prägen - Erleuchtung", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Erleuchtung':\n\nIhr verursacht 10% mehr Schaden, solange Ihr mehr als 70% Mana habt. Während Ihr weniger als 30% Mana habt, beträgt Eure Manaregeneration während des Zauberwirkens 10%." }
entries[415948] = { ["name"] = "Gürtel prägen - Zauberfrostblitz", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Zauberfrostblitz':\n\nSchleudert einen Zauberfrostblitz auf den Gegner, der [Quellwert] bis [Quellwert] Zauberfrostschaden verursacht und seine Bewegungsgeschwindigkeit 9 Sek. lang um 40% verringert. Der Schaden dieses Zaubers wird gegen den jeweils geringeren Frost- oder Arkanwiderstandswert des Ziels gerechnet und zählt sowohl als Frost- als auch als Arkanschaden.", ["unresolvedValues"] = true }
entries[415988] = { ["name"] = "Vahi Knochenspalter - Zentaurenkopf gegen Runenfragment eintauschen" }
entries[415991] = { ["name"] = "Helm prägen - Schmerz und Leid", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Schmerz und Leid':\n\n'Gedankenschlag', 'Gedankenstachel' und 'Gedankenschinden' setzen die Dauer von 'Schattenwort: Schmerz', 'Pest der Leere' oder 'Vampirberührung' auf Eurem Ziel auf das Maximum zurück. Es wird immer die Fähigkeit mit der geringsten verbleibenden Dauer aufgefrischt." }
entries[415995] = { ["name"] = "Brustteil prägen - Glücksfall", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Glücksfall':\n\nEure Heilung mit 'Blitzheilung' verringert die Zauberzeit Eures nächsten Einsatzes von 'Geringe Heilung', 'Heilung', 'Große Heilung' oder 'Gebet der Heilung' 20 Sek. lang um 20%. Bis zu 3-mal stapelbar." }
entries[415996] = { ["name"] = "Handschuhe prägen - Gedankenbrand", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Gedankenbrand':\n\nLöst eine Explosion von Schattenmagie aus, die dem Ziel und Gegnern innerhalb von 10 Metern um das Ziel herum 6 Sek. lang alle 1 Sek. [Quellwert] bis [Quellwert] Schattenschaden zufügt.", ["unresolvedValues"] = true }
entries[415997] = { ["name"] = "Brustteil prägen - Kraftvolle Seele", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Kraftvolle Seele':\n\n'Geringe Heilung', 'Heilung', 'Große Heilung' und 'Blitzheilung' verringern die verbleibende Dauer von 'Geschwächte Seele' auf den geheilten Zielen um 2 Sek. Zusätzlich erhalten Ziele Eures Zaubers 'Machtwort: Schild' 'Wut', wenn sie trotz absorbierten Schadens Schaden erleiden, und 'Zorn der Gerechtigkeit' wird durch von 'Machtwort: Schild' absorbiertem Schaden ausgelöst, als wäre es eine Heilung." }
entries[416002] = { ["name"] = "Gravierte Stiefel - Gladiatorhaltung", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Gladiatorhaltung':\n\nEine aggressive Haltung, die beim Tragen eines Schildes den Schaden um 10% und die Blockchance um 10% erhöht, dabei jedoch die Rüstung um 30% und die erzeugte Bedrohung um 30% verringert. Zusätzlich erhaltet Ihr 50% mehr Wut, wenn Eure Nahkampfangriffe einem Gegner Schaden zufügen, der Euch nicht als Ziel hat.\n\nWährend Ihr in der 'Gladiatorhaltung' einen Schild tragt, könnt Ihr sämtliche Fähigkeiten einsetzen, die auf andere Haltungen beschränkt sind." }
entries[416003] = { ["name"] = "Gürtel prägen - Zielstrebiger Furor", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Zielstrebiger Furor':\n\nWenn Ihr mit zwei Waffen kämpft, wird Eure Bewegungsgeschwindigkeit um 10% erhöht und Ihr erhaltet immer, wenn Euer automatischer Angriff das selbe Ziel wie Euer vorheriger automatischer Angriff trifft, 4% Angriffstempo, bis zu einem Maximum von 5 Stapeln. Hält 10 Sek. lang an oder bis Eure automatischen Angriffe ein anderes Ziel treffen." }
entries[416004] = { ["name"] = "Gürtel prägen - Blutwoge", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Blutwoge':\n\nBeim Einsatz von 'Heldenhafter Stoß', 'Blutdurst' und 'Wirbelwind' besteht eine Chance von 30%, dass Euer nächster Einsatz von 'Zerschmettern' innerhalb von 15 Sek. sofort eingesetzt wird, mit beiden Nahkampfwaffen zuschlägt und keine Wut kostet." }
entries[416005] = { ["name"] = "Gürtel prägen - Präzises Timing", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Genau zur rechten Zeit':\n\n'Zerschmettern' wird jetzt sofort eingesetzt, hat allerdings eine Abklingzeit von 6 Sek." }
entries[416008] = { ["name"] = "Hosen prägen - Immerwährende Gebrechen", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Euren Hosen mit der Rune 'Immerwährende Gebrechen':\n\n'Blutsauger', 'Seelendieb', 'Schattenblitz', 'Schattenspalten', 'Sengender Schmerz', 'Einäschern' und 'Heimsuchung' setzen die Dauer Eurer 'Verderbnis' auf dem Ziel auf das Maximum zurück." }
entries[416009] = { ["name"] = "Brustteil prägen - Dämonische Taktiken", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Dämonische Taktiken':\n\nErhöht die Chance für einen kritischen Nahkampf- oder Zaubertreffer von Euch und Eurem Dämon um 10%." }
entries[416014] = { ["name"] = "Stiefel prägen - Dämonisches Wissen", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Dämonisches Wissen':\n\nErhöht Zauberschaden und -heilung um einen Wert, der 3% der maximalen Ausdauer plus der Intelligenz Eures Dämons entspricht." }
entries[416015] = { ["name"] = "Armschienen prägen - Verbrennen", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Verbrennen':\n\nVerbrennt Euren Gegner, fügt ihm [Quellwert] bis [Quellwert] Schaden zu und erhöht jeglichen von Euch verursachten Feuerschaden 15 Sek. lang um 40%.", ["unresolvedValues"] = true }
entries[416017] = { ["name"] = "Stiefel prägen - Tanz des Tückischen", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Tanz des Tückischen':\n\nIhr und Euer Dämon erhaltet jedes Mal, wenn Ihr einem Gegner einen kritischen Treffer zufügt, eine Ausweichchance in Höhe von 70% Eurer kritischen Zaubertrefferchance. Ihr beide gewinnt außerdem 2% Eures maximalen Manas zurück." }
entries[416028] = { ["name"] = "Stiefel prägen - Geheiligter Schild", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Geheiligter Schild':\n\nJedes Mal, wenn das Ziel Schaden erleidet, wird es von einem geheiligten Schild umhüllt, der [Quellwert] Schaden absorbiert und die Chance des Paladins, mit 'Lichtblitz' einen kritischen Treffer zu erzielen, bis zu 6 Sek. lang um 50% erhöht. Zusätzlich heilen Eure Einsätze von 'Lichtblitz' Ziele mit 'Geheiligter Schild' im Verlauf von 12 Sek. um weitere 100% Gesundheit. Dieser Effekt kann nur einmal alle 6 Sek. auftreten. Hält 1 Min. lang an. Es kann immer nur jeweils ein Ziel mit diesem Zauber belegt sein.", ["unresolvedValues"] = true }
entries[416031] = { ["name"] = "Stiefel prägen - Die Kunst des Krieges", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Die Kunst des Krieges':\n\nEure kritischen Nahkampftreffer verringern die verbleibende Abklingzeit von 'Exorzismus' um 2 Sek., und die Manakosten von 'Exorzismus' werden um 80% verringert." }
entries[416035] = { ["name"] = "Stiefel prägen - Vom Licht behütet", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Vom Licht behütet':\n\nJedes Mal, wenn Ihr ein Ziel mit Eurer Nahkampfwaffe trefft, gewinnt Ihr 15 Sek. lang alle 3 Sek. 5% Eures maximalen Manas. Während dieser Manaregeneration ist der durch Eure Heilzauber geheilte Wert jedoch um 50% verringert." }
entries[416037] = { ["name"] = "Hosen prägen - Aurenmeisterschaft", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Aurenmeisterschaft':\n\nVerleiht allen durch Eure Fähigkeit 'Aura der Konzentration' gestärkten Zielen Immunität gegen Unterbrechungs- und Stilleeffekte. Die Effekte aller anderen Auren werden um 100% erhöht. Hält 6 Sek. lang an." }
entries[416042] = { ["name"] = "Brustteil prägen - Überleben des Stärkeren", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Überleben des Stärkeren':\n\nVerringert die Chance, dass Ihr einen kritischen Treffer durch Nahkampfangriffe erleidet, um 6% und verringert jeglichen erlittenen Schaden um 10%. Verringert den erlittenen Schaden zusätzlich um 10%, während Ihr in Bärengestalt oder Terrorbärengestalt seid." }
entries[416044] = { ["name"] = "Handschuhe prägen - Sonnenfeuer", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Sonnenfeuer':\n\nVerbrennt den Gegner und fügt ihm [Quellwert] bis [Quellwert] Naturschaden sowie im Verlauf von 12 Sek. [Quellwert] zusätzlichen Naturschaden zu.\n\nAußerdem wird, während Ihr in Bärengestalt, Katzengestalt oder Terrorbärengestalt seid, Euer 'Mondfeuer' durch 'Sonnenfeuer (Bär)' oder 'Sonnenfeuer (Katze)' ersetzt. Dieser Zauber profitiert von allen Effekten von 'Mondfeuer' und löst diese aus.\n\n'Sonnenfeuer (Bär)'\nVerbrennt den Gegner und fügt ihm [Quellwert] bis [Quellwert] Naturschaden sowie im Verlauf von 12 Sek. [Quellwert] zusätzlichen Naturschaden zu.\n\n'Sonnenfeuer (Katze)'\nVerbrennt den Gegner und fügt ihm [Quellwert] bis [Quellwert] Naturschaden sowie im Verlauf von 12 Sek. [Quellwert] zusätzlichen Naturschaden zu. Generiert 1 Combopunkt.", ["unresolvedValues"] = true }
entries[416046] = { ["name"] = "Handschuhe prägen - Schädelstoß", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Schädelstoß':\n\nStürmt auf ein Ziel innerhalb von 13 Metern zu und schlagt ihm gegen den Schädel, was das Wirken von Zaubern unterbricht und 2 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können. Gemeinsame Abklingzeit mit 'Wilde Attacke'." }
entries[416049] = { ["name"] = "Hosen prägen - Aufschlitzen", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Aufschlitzen':\n\nSchlitzt ein gegnerisches Ziel auf, was im Verlauf von 15 Sek. [Quellwert] Blutungsschaden und pro existierender Anwendung von 'Aufschlitzen' auf dem Ziel 20% Waffenschaden verursacht. Generiert hohe Bedrohung. Dieser Effekt ist bis zu 5-mal auf demselben Ziel stapelbar.", ["unresolvedValues"] = true }
entries[416050] = { ["name"] = "Brustteil prägen - Samenkorn des Lebens", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Samenkorn des Lebens':\n\nWenn Ihr mit Euren nicht regelmäßigen Heilzaubern einen kritischen Treffer erzielt, pflanzt Ihr dem Ziel für 50% des geheilten Wertes ein 'Samenkorn des Lebens' ein. Das Samenkorn wird erblühen, wenn das Ziel das nächste Mal Schaden erleidet oder nicht regelmäßige Heilung erhält. Hält 15 Sek. lang an." }
entries[416051] = { ["name"] = "Armschienen prägen - Feuer Elunes", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Feuer Elunes':\n\nEinige Eurer Zauber und Fähigkeiten verlängern die Dauer Eurer regelmäßigen Schadens- und Heileffekte auf ihrem Ziel:\n\n'Sternenfeuer' verlängert 'Mondfeuer' um 6 Sek.\n'Zorn' verlängert 'Sonnenfeuer' um 3 Sek.\n'Nachwachsen' verlängert 'Verjüngung' um 6 Sek.\n'Schreddern' verlängert 'Zerfetzen' um 2 Sek.\n\nJeder Effekt kann nur bis zur ursprünglichen Dauer verlängert werden." }
entries[416054] = { ["name"] = "Gürtel prägen - Kraftwoge", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Kraftwoge':\n\nJedes Mal, wenn Euer 'Flammenschock' Schaden verursacht, besteht eine Chance von 5%, dass die Abklingzeiten von 'Lavaeruption' und 'Kettenblitzschlag' abgeschlossen werden und Euer nächster Einsatz von 'Lavaeruption' oder 'Kettenblitzschlag' innerhalb von 10 Sek. ein Spontanzauber ist. Jedes Mal, wenn Eure 'Springflut' heilt, besteht eine Chance von 5%, dass Euer nächster Einsatz von 'Kettenheilung' innerhalb von 10 Sek. ein Spontanzauber ist. Zusätzlich erhaltet Ihr alle 5 Sek. Mana in Höhe von 15% Eurer Intelligenz." }
entries[416055] = { ["name"] = "Helm prägen - Geistige Gewandtheit", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Geistige Gewandtheit':\n\nSchaden mit 'Sturmschlag' zu verursachen, erhöht 30 Sek. lang Eure Angriffskraft um 150% Eurer Intelligenz und Euren Zauberschaden um 35% Eurer gesamten Angriffskraft." }
entries[416057] = { ["name"] = "Brustteil prägen - Heilender Regen", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Heilender Regen':\n\nWählt einen Bereich von 15 Metern um den anvisierten Spielercharakter aus und heilt alle Gruppenmitglieder des anvisierten Spielercharakters im Bereich pro Sekunde um [Quellwert] Gesundheit.", ["unresolvedValues"] = true }
entries[416062] = { ["name"] = "Umhang prägen - Kohärenz", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang\nPrägt Euren Umhang mit der Rune 'Kohärenz':\n\nDie Effektivität Eurer 'Kettenheilung' wird nur um 35% pro Übersprung verringert und die Effektivität von 'Kettenblitzschlag' nur um 20% Prozent pro Übersprung. Springt außerdem auf 1 zusätzliches Ziel über." }
entries[416066] = { ["name"] = "Helm prägen - Brennen", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Brennen':\n\nEuer 'Flammenschock' trifft jetzt bis zu 5 Ziele, hat eine 6 Sek. längere Effektdauer und verursacht 100% mehr Schaden. Zusätzlich wird Euer Zauberschaden um 150% Eurer Intelligenz erhöht, während Eure ausgerüstete Waffenhandwaffe mit 'Waffe der Flammenzunge' verzaubert ist." }
entries[416081] = { ["name"] = "Kohärenz", ["text"] = "Erhaltet die Fähigkeit 'Kohärenz':\n\nDie Effektivität Eurer 'Kettenheilung' wird nur um 35% pro Übersprung verringert und die Effektivität von 'Kettenblitzschlag' nur um 20% Prozent pro Übersprung. Springt außerdem auf 1 zusätzliches Ziel über." }
entries[416083] = { ["name"] = "Helm prägen - Katzenhafte Reflexe", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Katzenhafte Reflexe':\n\nErhöht Eure Ausweichchance um 20% und die Eures Begleiters um 9%. Außerdem wird die Abklingzeit Eurer Fähigkeit 'Flankenangriff' um 50% verringert." }
entries[416084] = { ["name"] = "Gürtel prägen - Aspekt der Viper", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Aspekt der Viper':\n\nDer Jäger nimmt die Aspekte einer Viper an. Jeder Eurer automatischen Distanz- und Nahkampfangriffe regeneriert Mana, der gesamte verursachte Schaden wird jedoch um 10% verringert. Zusätzlich erhaltet Ihr alle 3 Sek. 10% Eures maximalen Manas. Das gewonnene Mana basiert auf dem Tempo Eurer Waffe. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[416085] = { ["name"] = "Helm prägen - Sichern und Laden", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Sichern und Laden':\n\nJedes Mal, wenn Ihr eine Falle platziert, kostet Eure nächste Schussfähigkeit (mit Ausnahme von 'Streuschuss') innerhalb von 20 Sek. kein Mana und löst keine Abklingzeit aus." }
entries[416086] = { ["name"] = "Gürtel prägen - Nahkampfspezialist", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Nahkampfspezialist':\n\n'Raptorstoß' ist nun ein Spontanzauber, und 'Mungobiss' und 'Raptorstoß' haben bei jedem Angriff eine Chance von 40%, die Abklingzeiten von 'Mungobiss' und 'Raptorstoß' abzuschließen." }
entries[416087] = { ["name"] = "Gürtel prägen - Tödlicher Schuss", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Tödlicher Schuss':\n\nIhr versucht, ein verletztes Ziel mit einem Distanzangriff zu töten, der 100% Waffenschaden plus [Quellwert] verursacht. 'Tödlicher Schuss' hat keine Minimaldistanz, und seine Abklingzeit wird zurückgesetzt, wenn er gegen einen Gegner mit 20% oder weniger Gesundheit eingesetzt wird.", ["unresolvedValues"] = true }
entries[416089] = { ["name"] = "Stiefel prägen - Flügeldrachenstoß", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel" }
entries[416090] = { ["name"] = "Helm prägen - Schneller Tod", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Schneller Tod':\n\nVerringert die Abklingzeit von 'Schnellfeuer' um 80%, 'Schnellfeuer' erhöht zusätzlich das Nahkampfangriffstempo um 40% und Eure nächste Schussfähigkeit innerhalb von 20 Sek., nachdem Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, verursacht 20% mehr Schaden." }
entries[416091] = { ["name"] = "Hosen prägen - Scharfschützentraining", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Scharfschützentraining':\n\nDie kritische Trefferchance Eurer Schussfähigkeiten ist um 2% erhöht, wenn Ihr Euch in den letzten 2 Sek. nicht bewegt habt. Dieser Effekt stapelt sich pro Sekunde bis auf maximal 5 Stapel. Bei 2 oder mehr Stapeln kann 'Gezielter Schuss' sofort eingesetzt werden. Während Ihr Euch bewegt, verliert Ihr 1 Stapel pro Sekunde." }
entries[416093] = { ["name"] = "Armschienen prägen - Raptorenfuror", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Raptorenfuror':\n\nEuer 'Raptorstoß' erhöht den durch 'Raptorstoß' und 'Mungobiss' verursachten Schaden 30 Sek. lang um 15%. Bis zu 5-mal stapelbar. Nachfolgende Einsätze verlängern nicht die Dauer des Effekts." }
