entries[417141] = { ["name"] = "Berserker", ["text"] = "Sofort 3 min Abklingzeit\nWenn aktiviert, lässt diese Fähigkeit 'Zerfleischen (Bär)' und 'Aufschlitzen' bis zu 3 Ziele treffen. 'Aufschlitzen' kostet keine Wut und 'Zerfleischen (Bär)' unterliegt keiner Abklingzeit. In Katzengestalt werden die Energiekosten aller Eurer Fähigkeiten um 50% verringert. Hält 15 Sek. lang an. Erfordert Katzengestalt, Bärengestalt oder Terrorbärengestalt.\n\nEntfernt sofort Furchteffekte und macht Euch während seiner Dauer gegen sie immun." }
entries[417145] = { ["name"] = "Aufspießen", ["text"] = "Wenn Ihr ein Ziel mit 'Aufschlitzen', 'Prankenhieb' oder 'Zermalmen' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Zerfleischen (Bär)' abgeschlossen und 10 Wut erzeugt wird. Wenn Ihr ein Ziel mit 'Zerfleischen' (Katze) oder 'Schreddern' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Tigerfuror' abgeschlossen wird.\n(Procchance: 15%, 100ms Abklingzeit)" }
