entries[417440] = { ["name"] = "Hauen (Bär)", ["text"] = "10 Wut 8 Meter Reichweite\nSpontanzauber 6 sek. Abklingzeit\nBenötigt Bärengestalt, Terrorbärengestalt\nTrifft Gegner in der Nähe, fügt ihnen [45 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 + 0.092 * Angriffskraft] Blutungsschaden zu und lässt sie 15 Sek. lang zusätzlich für [12 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 * 5 + 0.125 * Angriffskraft] Schaden bluten. Bei Anwendung in Bärengestalt ist dieser Effekt bis zu 3-mal stapelbar." }
entries[417441] = { ["name"] = "Hauen (Bär)" }
entries[417448] = { ["name"] = "Hauen (Katze)", ["text"] = "40 Energie 8 Meter Reichweite\nSofort\nBenötigt Katzengestalt\nTrifft Gegner in der Nähe, fügt ihnen [60 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 + 0.104 * Angriffskraft] Blutungsschaden zu und lässt sie 15 Sek. lang zusätzlich für [40 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 * 5 + 0.0661 * 5 * Angriffskraft] Schaden bluten. Gewährt 1 Combopunkt." }
entries[417450] = { ["name"] = "Hauen (Katze)" }
entries[417453] = { ["name"] = "Hauen (Katze)", ["text"] = "Erhaltet mehrere neue dämonische Fähigkeiten: 'Unterbrechen', 'Dämonischer Ansturm', 'Dämonisches Heulen' und 'Infernalischer Schlag'.\n\nErstickt Euren Gegner mit einer Welle schattenhafter Energie, die 10 Schaden verursacht, das Wirken von Zaubern unterbricht und 5 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können.\n\nStürmt auf einen Gegner zu und betäubt ihn für 1 Sek. Kann nicht im Kampf verwendet werden.\n\nZwingt alle Gegner in der Nähe 6 Sek. lang, ihre Angriffe auf Euch zu konzentrieren.\n\nSpringt durch die Luft und schmettert auf alle Gegner im Umkreis von 8 Metern um das Zielgebiet hinab, verursacht 100 Schattenschaden und betäubt sie für 2 Sek." }
