entries[425336] = { ["name"] = "Schamanistische Wut", ["text"] = "Sofort 1 min Abklingzeit\nReduziert sämtlichen von Euch erlittenen Schaden um 20% und Ihr regeneriert 15 Sek. lang pro Sekunde Mana in Höhe von 5% Eures maximalen Manas. Eure Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern erhalten zudem Mana in Höhe von 18% des von Euch auf diese Weise bezogenen Manas." }
entries[425339] = { ["name"] = "Schmelzschlag", ["text"] = "18% von Grundmana\nSofort 6 sek. Abklingzeit\nÜberzieht bis zu 10 Gegner in einem kegelförmigen Bereich vor Euch mit [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Angriffskraft] bis [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Angriffskraft] Feuerschaden. Diese Fähigkeit generiert eine große Menge Bedrohung. Der regelmäßige Schaden von 'Flammenschock' hat eine Chance von 10%, die Abklingzeit von 'Schmelzschlag' abzuschließen." }
entries[425340] = { ["name"] = "Schmelzschlag", ["text"] = "Erhaltet die Fähigkeit 'Schmelzschlag':\n\nÜberzieht bis zu 10 Gegner in einem kegelförmigen Bereich vor Euch mit [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Angriffskraft] bis [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Angriffskraft] Feuerschaden. Diese Fähigkeit generiert eine große Menge Bedrohung. Der regelmäßige Schaden von 'Flammenschock' hat eine Chance von 10%, die Abklingzeit von 'Schmelzschlag' abzuschließen." }
entries[425341] = { ["name"] = "Großer Geisterwolf", ["text"] = "Erhaltet die Fähigkeit 'Großer Geisterwolf':\n\nEure Fähigkeit 'Geisterwolf' kann nun drinnen benutzt werden und verringert sämtlichen erlittenen Schaden um 10%, so lange sie aktiv ist." }
entries[425343] = { ["name"] = "Hosen prägen - Großer Geisterwolf", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Großer Geisterwolf':\n\nEure Fähigkeit 'Geisterwolf' kann nun drinnen benutzt werden und verringert sämtlichen erlittenen Schaden um 10%, so lange sie aktiv ist." }
entries[425344] = { ["name"] = "Handschuhe prägen - Schmelzschlag", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Schmelzschlag':\n\nÜberzieht bis zu 10 Gegner in einem kegelförmigen Bereich vor Euch mit [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Angriffskraft] bis [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Angriffskraft] Feuerschaden. Diese Fähigkeit generiert eine große Menge Bedrohung. Der regelmäßige Schaden von 'Flammenschock' hat eine Chance von 10%, die Abklingzeit von 'Schmelzschlag' abzuschließen." }
entries[425412] = { ["name"] = "Rasender Angriff", ["text"] = "Während Ihr Zweihandwaffen tragt, ist Euer Angriffstempo um 40% erhöht und Eure erfolgreichen Nahkampfangriffe erzeugen 2 zusätzliche Wut oder 4 zusätzliche Wut, wenn sie kritische Treffer sind." }
entries[425415] = { ["name"] = "Wutanfall" }
entries[425418] = { ["name"] = "Von Wut zerfressen", ["text"] = "Versetzt Euch 12 Sek. lang in einen Wutzustand (und aktiviert Fähigkeiten, die einen Wutzustand erfordern), nachdem Ihr 60 Wut überschritten habt. Außerdem trifft 'Wirbelwind' auch mit Schildhandwaffen, während Ihr Euch in einem Wutzustand befindet." }
entries[425421] = { ["name"] = "Kriegstreiber", ["text"] = "Eure Fähigkeiten 'Sturmangriff', 'Abfangen' und 'Einschreiten' sind nun während des Kampfes und in jeder Haltung nutzbar und werden bei Aktivierung jegliche bewegungseinschränkenden Effekte entfernen." }
entries[425428] = { ["name"] = "Rasanter Schlag", ["text"] = "Erlangt die Fähigkeit 'Rasanter Schlag':\n\nEin tollkühner, sofortiger Nahkampfangriff mit Eurer Zweihandwaffe, der (Angriffskraft * 30 / 100) bis (Angriffskraft * 40 / 100) körperlichen Schaden verursacht. Diese Fähigkeit profitiert von allen Effekten von 'Heldenhafter Stoß' und löst diese aus." }
entries[425429] = { ["name"] = "Wütender Schlag", ["text"] = "Erhaltet die Fähigkeit 'Wütender Schlag':\n\nEin wilder Schlag, der 115% Waffenschaden verursacht, jedoch nur eingesetzt werden kann, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist. Jede andere Nahkampffähigkeit, die eingesetzt wird, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist, verringert die verbleibende Abklingzeit von 'Wütender Schlag' um 1 Sek." }
