entries[427084] = { ["name"] = "Armschienen prägen - Abrisskommando", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Abrisskommando':\n\nEure kritischen Nahkampftreffer machen Euch wütend (und aktivieren Fähigkeiten, für die Ihr wütend sein müsst) und erhöhen den Schaden von 'Tödlicher Stoß', 'Blutdurst' und 'Schildschlag' 12 Sek. lang um 10%." }
