entries[427144] = { ["name"] = "Gegenschlag der Leere", ["text"] = "Sofort\nDieser Gegenstand ist mit der rohen Macht der Leere erfüllt. Wenn der Träger angegriffen wird, hat dieser Gegenstand eine hohe Chance, einen schrecklichen Fluch zu wirken, durch den der Angreifer 15 Sek. lang zusätzlichen Schaden aus allen Quellen erleidet.\n(Procchance: 25%)" }
