entries[427712] = { ["name"] = "Pandemie", ["text"] = "Regelmäßiger Schaden durch Eure Fähigkeiten 'Verderbnis', 'Instabiles Gebrechen', 'Fluch der Pein', 'Feuerbrand', 'Fluch der Verdammnis' und 'Lebensentzug' kann jetzt kritisch treffen.\nModifies Critical Strike Damage +101%:\nAnrufung , Anrufung , Anrufung , Fluch der Pein , Fluch der Pein , Fluch der Pein , Fluch der Pein , Fluch der Pein , Fluch der Pein , Fluch der Verdammnis , Lebensentzug , Lebensentzug , Lebensentzug , Lebensentzug , Verderbnis , Verderbnis , Verderbnis , Verderbnis , Verderbnis , Verderbnis , Verderbnis" }
