entries[427717] = { ["name"] = "Instabiles Gebrechen", ["text"] = "15% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nSchattenenergie zerstört langsam das Ziel und verursacht im Verlauf von 18 Sek. insgesamt [Quellwert] Schaden. Sollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende [Quellwert] Schaden und wird 5 Sek. lang zum Schweigen gebracht. Es kann pro Hexenmeister jeweils nur ein Effekt von 'Instabiles Gebrechen' oder 'Feuerbrand' gleichzeitig auf einem beliebigen Ziel aktiv sein.", ["unresolvedValues"] = true }
