entries[427726] = { ["name"] = "Feuerbrandaura", ["text"] = "Sofort\nImmer wenn ein Gegner Euch im Nahkampf angreift, werden Gegner in der Nähe verbrannt und erleiden [Quellwert] Schaden. Kann nicht häufiger als einmal pro Sekunde auftreten. Verringert außerdem sämtlichen erlittenen Magieschaden um 10% und erhöht den verursachten Feuerschaden um 10%. Hält bis Abbruch lang an.\n(1s Abklingzeit)", ["unresolvedValues"] = true }
