entries[428424] = { ["name"] = "Phönixbindungen", ["text"] = "Wirken in 5.125 sek.\nReagenzien:\nWollstoffballen (6), Fläschchen Öl (2), Feiner Faden (2)\nPhönixbindungen\nWird beim Anlegen gebunden\nHandgelenke Stoff\n21 Rüstung\nHaltbarkeit 30 / 30\n25\nAnlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 13." }
