entries[428713] = { ["name"] = "Baumrinde", ["text"] = "15% von Grundmana 40 Meter Reichweite\nSofort 1 min Abklingzeit\nDie Haut des Ziels wird hart wie Rinde. Erlittener körperlicher Schaden wird um 20% verringert. Während des Schutzes verursacht erlittener Schaden keine Verzögerung beim Zaubern. Hält 15 Sek. lang an." }
entries[428717] = { ["name"] = "T.N.T.", ["text"] = "Erhöht von 'Explosivschuss' und all Euren Schadensfallen verursachten Schaden um 10%. Zudem werden der anfängliche Schaden von 'Sprengfalle' sowie der gesamte regelmäßige Schaden Eurer 'Feuerbrandfalle' um 25% Eurer Nahkampf- oder Distanzangriffskraft erhöht." }
