entries[428726] = { ["name"] = "Fokussiertes Feuer", ["text"] = "100 Meter Reichweite\nSofort\nVerbraucht alle Anwendungen von 'Raserei' auf Eurem Tier, was Eurer Distanzangriffstempo um 3% erhöht und Eurem Tier 4 Fokus für jede verbrauchte Anwendung von 'Raserei' verleiht. Hält 20 Sek. lang an.\n\nImmer wenn Euer Tier einen einfachen Angriff ausführt, erhält es 'Raserei', und sein Nahkampfangriffstempo wird 10 Sek. lang um 6% erhöht. Bis zu 5-mal stapelbar." }
entries[428728] = { ["name"] = "Raserei", ["text"] = "100 Meter Reichweite\nSofort\nErhöht das Nahkampfangriffstempo Eures Tiers 10 Sek. lang um 6%." }
