entries[428739] = { ["name"] = "Tieffrieren", ["text"] = "9% von Grundmana 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBetäubt das Ziel für 5 Sek.. Funktioniert nur bei eingefrorenen Zielen. Fügt Zielen, die dauerhaft gegen Betäubungseffekte immun sind, [Quellwert] bis [Quellwert] Schaden zu. Dieser Schaden profitiert von 'Vergletscherung', braucht aber keine Stapel davon auf.", ["unresolvedValues"] = true }
