entries[428741] = { ["name"] = "Glühende Rüstung", ["text"] = "28% von Grundmana\nSofort\nFügt einem Gegner [Quellwert] Feuerschaden zu, wenn Ihr getroffen werdet. Erhöht Eure kritische Zaubertrefferchance um 5% und verringert die Chance, dass Ihr kritische Treffer erleidet, um 5%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.", ["unresolvedValues"] = true }
