entries[428861] = { ["name"] = "Verzerrung", ["text"] = "35% von Grundmana 100 Meter Reichweite\nSofort 30 sek. Abklingzeit\nTeleportiert Euch dahin zurück, wo Ihr zuletzt 'Blinzeln' gewirkt habt, und schließt die Abklingzeit von 'Blinzeln' ab. Lässt sich nur innerhalb von 10 Sek. nach dem Wirken von 'Blinzeln' nutzen." }
entries[428863] = { ["name"] = "Verzerrung", ["text"] = "Erhaltet die Fähigkeit 'Verzerrung':\n\nTeleportiert Euch dahin zurück, wo Ihr zuletzt 'Blinzeln' gewirkt habt, und schließt die Abklingzeit von 'Blinzeln' ab. Lässt sich nur innerhalb von 10 Sek. nach dem Wirken von 'Blinzeln' nutzen." }
