entries[428878] = { ["name"] = "Qualfeuerblitz", ["text"] = "20% von Grundmana 35 Meter Reichweite\nWirken in 2.5 sek.\nEntfesselt eine realitätsverzerrende Explosion aus roher Magie auf Euren Gegner, die ihm zwischen [Quellwert] und [Quellwert] Schimärenschaden zufügt.\n\nErhöht [Quellwert] lang den Schaden Eurer Fähigkeiten 'Qualfeuerblitz' und 'Pyroschlag' um 25% und verringert Eure Willenskraft um 20%. Bis zu 5-mal stapelbar. Fällt Eure Willenskraft auf 0, sterbt Ihr.\n\nDer Schaden dieses Zaubers wird gegen den geringsten Wert vom Arkan-, Feuer- und Frostwiderstand des Ziels gerechnet.", ["unresolvedValues"] = true }
entries[428885] = { ["name"] = "Zeitanomalie", ["text"] = "11% von Grundmana 40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nSchleudert eine Kugel aus Temporalenergie, die sich langsam vorwärts bewegt und allen nahen Gruppenmitgliedern jede 2 Sek. einen Schild gewährt, der 15 Sek. lang [Quellwert] Schaden absorbiert. Dieser Schild häuft zusätzlichen Wert an, wenn Gruppenmitglieder in der Nähe der Kugel bleiben.", ["unresolvedValues"] = true }
