entries[428909] = { ["name"] = "Anmut des Lichts", ["text"] = "Euer Zauber 'Heiliges Licht' verringert die Zauberzeit Eures nächsten Einsatzes von 'Heiliges Licht' um 0.5 Sek. Hält 15 Sek. lang an." }
entries[428912] = { ["name"] = "Anmut des Lichts", ["text"] = "Sofort\nModifies Cast Time -499:\nGöttliches Licht , Heiliges Licht , Heiliges Licht , Heiliges Licht , Heiliges Licht , Heiliges Licht , Heiliges Licht , Heiliges Licht , Heiliges Licht , Heiliges Licht" }
