entries[429125] = { ["name"] = "Eisige Adern", ["text"] = "3% von Grundmana\nSofort 3 min Abklingzeit\nBeschleunigt Euer Wirken von Zaubern, erhöht das Zaubertempo um 20% und verringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Wirken von Zaubern um 100%. Hält 20 Sek. lang an." }
entries[429133] = { ["name"] = "Verbessertes Refugium", ["text"] = "Erhöht den durch Euren 'Segen des Refugiums' verhinderten Schaden um 100% und erhöht den durch Euren 'Segen des Refugiums' verursachten Schaden um 20% Eures Schildblockwerts." }
entries[429139] = { ["name"] = "Zorn", ["text"] = "Der Schaden Eurer 'Weihe' kann nun kritisch treffen, und der Schaden Eurer Zauber 'Exorzismus', 'Heiliger Schock', 'Sonnenlicht', 'Heiliger Zorn' und 'Weihe' erhält eine zusätzliche Chance auf kritische Treffer, die der kritischen Trefferchance Eurer Nahkampftreffer entspricht." }
entries[429142] = { ["name"] = "Fanatismus", ["text"] = "Erhöht Eure kritische Trefferchance mit Heiligzaubern um 18%. Zudem heilen Eure kritischen Heilzauber das Ziel im Verlauf von 12 Sek. für 60% der geheilten Menge." }
entries[429144] = { ["name"] = "Reinigende Macht", ["text"] = "Verringert die Abklingzeit von 'Exorzismus' und 'Heiliger Zorn' um 50%. 'Heiliger Zorn' kann jetzt auf jedes Ziel gewirkt werden und betäubt dämonische sowie untote Ziele für 2 Sek." }
entries[429145] = { ["name"] = "Heiliger Zorn", ["text"] = "645 ManaWirken in 2 sek. 1 min Abklingzeit\nSchleudert Blitze heiliger Macht in alle Richtungen, fügt dabei allen Zielen im Umkreis von 20 Metern 368 bis 435 Heiligschaden zu und betäubt dämonische sowie untote Ziele für 2 Sek." }
entries[429146] = { ["name"] = "Heiliger Zorn", ["text"] = "805 ManaWirken in 2 sek. 1 min Abklingzeit\nSchleudert Blitze heiliger Macht in alle Richtungen, fügt dabei allen Zielen im Umkreis von 20 Metern 490 bis 576 Heiligschaden zu und betäubt dämonische sowie untote Ziele für 2 Sek." }
