entries[429151] = { ["name"] = "Hammer des Zorns", ["text"] = "12% von Grundmana 30 Meter Reichweite\nSofort\nSchleudert einen Hammer, der einem Gegner [300 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) + 0.15 * Zaubermacht + 0.15 * Angriffskraft] bis [300 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) + 0.15 * Zaubermacht + 0.15 * Angriffskraft] Heiligschaden zufügt. Nur auf Ziele anwendbar, die 20% oder weniger Gesundheit haben." }
entries[429152] = { ["name"] = "Verbesserter Hammer des Zorns", ["text"] = "'Hammer des Zorns' ist nun ein Spontanzauber und seine Abklingzeit wird immer dann abgeschlossen, wenn er einem Gegner mit weniger als 10% Gesundheit Schaden zufügt." }
