entries[429242] = { ["name"] = "Armschienen prägen - Anmut des Lichts", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Anmut des Lichts':\n\nEuer Zauber 'Heiliges Licht' verringert die Zauberzeit Eures nächsten Einsatzes von 'Heiliges Licht' um 0.5 Sek. Hält 15 Sek. lang an." }
entries[429243] = { ["name"] = "Anmut des Lichts", ["text"] = "Erhaltet die Fähigkeit 'Anmut des Lichts':\n\nEuer Zauber 'Heiliges Licht' verringert die Zauberzeit Eures nächsten Einsatzes von 'Heiliges Licht' um 0.5 Sek. Hält 15 Sek. lang an." }
entries[429245] = { ["name"] = "Verbessertes Refugium", ["text"] = "Erhaltet die Fähigkeit 'Verbessertes Refugium':\n\nErhöht den durch Euren 'Segen des Refugiums' verhinderten Schaden um 100% und erhöht den durch Euren 'Segen des Refugiums' verursachten Schaden um 20% Eures Schildblockwerts." }
entries[429247] = { ["name"] = "Helm prägen - Verbessertes Refugium", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Verbessertes Refugium':\n\nErhöht den durch Euren 'Segen des Refugiums' verhinderten Schaden um 100% und erhöht den durch Euren 'Segen des Refugiums' verursachten Schaden um 20% Eures Schildblockwerts." }
entries[429248] = { ["name"] = "Zorn", ["text"] = "Erhaltet die Fähigkeit 'Zorn':\n\nDer Schaden Eurer 'Weihe' kann nun kritisch treffen, und der Schaden Eurer Zauber 'Exorzismus', 'Heiliger Schock', 'Sonnenlicht', 'Heiliger Zorn' und 'Weihe' erhält eine zusätzliche Chance auf kritische Treffer, die der kritischen Trefferchance Eurer Nahkampftreffer entspricht." }
entries[429249] = { ["name"] = "Helm prägen - Zorn", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Zorn':\n\nDer Schaden Eurer 'Weihe' kann nun kritisch treffen, und der Schaden Eurer Zauber 'Exorzismus', 'Heiliger Schock', 'Sonnenlicht', 'Heiliger Zorn' und 'Weihe' erhält eine zusätzliche Chance auf kritische Treffer, die der kritischen Trefferchance Eurer Nahkampftreffer entspricht." }
entries[429250] = { ["name"] = "Fanatismus", ["text"] = "Erhaltet die Fähigkeit 'Fanatismus':\n\nErhöht Eure kritische Trefferchance mit Heiligzaubern um 18%. Zudem heilen Eure kritischen Heilzauber das Ziel im Verlauf von 12 Sek. für 60% der geheilten Menge." }
entries[429251] = { ["name"] = "Helm prägen - Fanatismus", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Fanatismus':\n\nErhöht Eure kritische Trefferchance mit Heiligzaubern um 18%. Zudem heilen Eure kritischen Heilzauber das Ziel im Verlauf von 12 Sek. für 60% der geheilten Menge." }
entries[429254] = { ["name"] = "Reinigende Macht", ["text"] = "Erhaltet die Fähigkeit 'Reinigende Macht':\n\nVerringert die Abklingzeit von 'Exorzismus' und 'Heiliger Zorn' um 50%. 'Heiliger Zorn' kann jetzt auf jedes Ziel gewirkt werden und betäubt dämonische sowie untote Ziele für 2 Sek." }
entries[429255] = { ["name"] = "Armschienen prägen - Reinigende Macht", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Reinigende Macht':\n\nVerringert die Abklingzeit von 'Exorzismus' und 'Heiliger Zorn' um 50%. 'Heiliger Zorn' kann jetzt auf jedes Ziel gewirkt werden und betäubt dämonische sowie untote Ziele für 2 Sek." }
entries[429259] = { ["name"] = "Verbesserter Hammer des Zorns", ["text"] = "Erhaltet die Fähigkeit 'Verbesserter Hammer des Zorns':\n\n'Hammer des Zorns' ist nun ein Spontanzauber und seine Abklingzeit wird immer dann abgeschlossen, wenn er einem Gegner mit weniger als 10% Gesundheit Schaden zufügt." }
entries[429261] = { ["name"] = "Armschienen prägen - Verbesserter Hammer des Zorns", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Hammer des Zorns':\n\n'Hammer des Zorns' ist nun ein Spontanzauber und seine Abklingzeit wird immer dann abgeschlossen, wenn er einem Gegner mit weniger als 10% Gesundheit Schaden zufügt." }
entries[429283] = { ["name"] = "Pandemie", ["text"] = "Erhaltet die Fähigkeit 'Pandemie':\n\nRegelmäßiger Schaden durch Eure Fähigkeiten 'Verderbnis', 'Instabiles Gebrechen', 'Fluch der Pein', 'Feuerbrand', 'Fluch der Verdammnis' und 'Lebensentzug' kann jetzt kritisch treffen." }
entries[429303] = { ["name"] = "Tieffrieren", ["text"] = "Erhaltet die Fähigkeit 'Tieffrieren':\n\nBetäubt das Ziel für 5 Sek.. Funktioniert nur bei eingefrorenen Zielen. Fügt Zielen, die dauerhaft gegen Betäubungseffekte immun sind, [Quellwert] bis [Quellwert] Schaden zu. Dieser Schaden profitiert von 'Vergletscherung', braucht aber keine Stapel davon auf.", ["unresolvedValues"] = true }
entries[429304] = { ["name"] = "Helm prägen - Tieffrieren", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Tieffrieren':\n\nBetäubt das Ziel für 5 Sek.. Funktioniert nur bei eingefrorenen Zielen. Fügt Zielen, die dauerhaft gegen Betäubungseffekte immun sind, [Quellwert] bis [Quellwert] Schaden zu. Dieser Schaden profitiert von 'Vergletscherung', braucht aber keine Stapel davon auf.", ["unresolvedValues"] = true }
entries[429305] = { ["name"] = "Zeitanomalie", ["text"] = "Erhaltet die Fähigkeit 'Zeitanomalie':\n\nSchleudert eine Kugel aus Temporalenergie, die sich langsam vorwärts bewegt und allen nahen Gruppenmitgliedern jede 2 Sek. einen Schild gewährt, der 15 Sek. lang [Quellwert] Schaden absorbiert. Dieser Schild häuft zusätzlichen Wert an, wenn Gruppenmitglieder in der Nähe der Kugel bleiben.", ["unresolvedValues"] = true }
entries[429306] = { ["name"] = "Helm prägen - Zeitanomalie", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Zeitanomalie':\n\nSchleudert eine Kugel aus Temporalenergie, die sich langsam vorwärts bewegt und allen nahen Gruppenmitgliedern jede 2 Sek. einen Schild gewährt, der 15 Sek. lang [Quellwert] Schaden absorbiert. Dieser Schild häuft zusätzlichen Wert an, wenn Gruppenmitglieder in der Nähe der Kugel bleiben.", ["unresolvedValues"] = true }
entries[429307] = { ["name"] = "Glühende Rüstung", ["text"] = "Erhaltet die Fähigkeit 'Glühende Rüstung':\n\nFügt einem Gegner [Quellwert] Feuerschaden zu, wenn Ihr getroffen werdet. Erhöht Eure kritische Zaubertrefferchance um 5% und verringert die Chance, dass Ihr kritische Treffer erleidet, um 5%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.", ["unresolvedValues"] = true }
entries[429308] = { ["name"] = "Armschienen prägen - Glühende Rüstung", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Glühende Rüstung':\n\nFügt einem Gegner [Quellwert] Feuerschaden zu, wenn Ihr getroffen werdet. Erhöht Eure kritische Zaubertrefferchance um 5% und verringert die Chance, dass Ihr kritische Treffer erleidet, um 5%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.", ["unresolvedValues"] = true }
entries[429309] = { ["name"] = "Armschienen prägen - Verzerrung", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Verzerrung':\n\nTeleportiert Euch dahin zurück, wo Ihr zuletzt 'Blinzeln' gewirkt habt, und schließt die Abklingzeit von 'Blinzeln' ab. Lässt sich nur innerhalb von 10 Sek. nach dem Wirken von 'Blinzeln' nutzen." }
entries[429310] = { ["name"] = "Qualfeuerblitz", ["text"] = "Erhaltet die Fähigkeit 'Qualfeuerblitz':\n\nEntfesselt eine realitätsverzerrende Explosion aus roher Magie auf Euren Gegner, die ihm zwischen [Quellwert] und [Quellwert] Schimärenschaden zufügt.\n\nErhöht [Quellwert] lang den Schaden Eurer Fähigkeiten 'Qualfeuerblitz' und 'Pyroschlag' um 25% und verringert Eure Willenskraft um 20%. Bis zu 5-mal stapelbar. Fällt Eure Willenskraft auf 0, sterbt Ihr.\n\nDer Schaden dieses Zaubers wird gegen den geringsten Wert vom Arkan-, Feuer- und Frostwiderstand des Ziels gerechnet.", ["unresolvedValues"] = true }
entries[429311] = { ["name"] = "Armschienen prägen - Qualfeuerblitz", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Qualfeuerblitz':\n\nEntfesselt eine realitätsverzerrende Explosion aus roher Magie auf Euren Gegner, die ihm zwischen [Quellwert] und [Quellwert] Schimärenschaden zufügt.\n\nErhöht [Quellwert] lang den Schaden Eurer Fähigkeiten 'Qualfeuerblitz' und 'Pyroschlag' um 25% und verringert Eure Willenskraft um 20%. Bis zu 5-mal stapelbar. Fällt Eure Willenskraft auf 0, sterbt Ihr.\n\nDer Schaden dieses Zaubers wird gegen den geringsten Wert vom Arkan-, Feuer- und Frostwiderstand des Ziels gerechnet.", ["unresolvedValues"] = true }
