entries[429350] = { ["name"] = "Destroy The Box - After Phase", ["text"] = "10 Meter Reichweite\nWirken in 4 sek.\nVersucht, die Leere mit dem Licht zu kontern und die Kiste zu zerstören." }
entries[429351] = { ["name"] = "Extraplanare Spinnenseidenstiefel", ["text"] = "Wirken in 45 sek.\nReagenzien:\nSplitter der Leere , Spinnenseidenstiefel\nExtraplanare Spinnenseidenstiefel\nWird beim Aufheben gebunden\nEinzigartig anlegbar: [Void-Touched] (1)Füße Stoff\n35 Rüstung\n+5 Ausdauer\n+5 Intelligenz\n+6 Willenskraft\nHaltbarkeit 50 / 50\n25\nBenötigtSchneiderei\n(100)\nBenutzen: Tretet zeitweise in eine andere Existenzebene ein, was sofort die Bedrohung reduziert und allen erlittenen und verursachten Schaden 6 Sek. lang um 30% verringert. (10 Min Abklingzeit)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 7.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%." }
