entries[429748] = { ["name"] = "Schneller Schlag", ["text"] = "Ersetzt Eure Fähigkeit 'Heldenhafter Stoß' durch 'Schneller Schlag':\n\nEin tollkühner, sofortiger Nahkampfangriff mit Eurer Zweihandwaffe, der (Angriffskraft * 30 / 100) bis (Angriffskraft * 40 / 100) körperlichen Schaden verursacht. Diese Fähigkeit profitiert von allen Effekten von 'Heldenhafter Stoß' und löst diese aus." }
entries[429765] = { ["name"] = "Rasanter Schlag", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Zweihändig\nEin tollkühner, sofortiger Nahkampfangriff mit Eurer Zweihandwaffe, der (Angriffskraft * 30 / 100) bis (Angriffskraft * 40 / 100) körperlichen Schaden verursacht. Diese Fähigkeit profitiert von allen Effekten von 'Heldenhafter Stoß' und löst diese aus." }
entries[429820] = { ["name"] = "Sternenregen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nFügt 10 Sek. lang Gegnern im ausgewählten Gebiet alle 2 Sek. 118 bis 132 Arkanschaden zu." }
entries[429821] = { ["name"] = "Sengpfeil", ["text"] = "50 Meter Reichweite\nBenötigt Distanzwaffe\nReagenzien:\nFeuerteer\nSchießt einen Flammenpfeil auf einen Gegner und fügt Waffenschaden plus 150 Schaden zu. Jeglicher verursachte Schaden basiert auf Feuermagie." }
entries[429822] = { ["name"] = "Spalten", ["text"] = "15 Meter Reichweite\nNächster Nahkampf\nFügt einem Gegner und seinen nächsten Verbündeten normalen Schaden zu. Wirkt auf bis zu 5 Ziele." }
entries[429823] = { ["name"] = "Mondfeuer", ["text"] = "15% von Grundmana 50 Meter Reichweite\nSofort\nFügt einem Gegner 285 bis 315 Arkanschaden zu und dann 12 Sek. lang alle 3 Sek. zusätzlich 71 bis 79 Schaden." }
entries[429825] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nTrifft einen Gegner mit einem Blitzschlag, der auf einen Gegner in der Nähe überspringt. Der Zauber wirkt sich auf bis zu 80 Ziele aus und verursacht bei jedem folgenden Ziel immer größeren Naturschaden." }
