entries[430397] = { ["name"] = "Blackfathom-Wetzstein", ["text"] = "Wirken in 8 sek.\nReagenzien:\nGrober Wetzstein , Geringe Magieessenz\nBlackfathom-Wetzstein\nBenutzen: Erhöht die Trefferchance 30 Min. lang um 2%, wenn es auf eine Waffe angewendet wird. Dies hat außerhalb der Blackfathom-Tiefe keinen Effekt.\n\"Diese geheimnisvollen verzauberten Steine scheinen immer heller zu leuchten, je tiefer Ihr in Blackfathom hinabsteigt.\"" }
