entries[430409] = { ["name"] = "Blackfathom-Manaöl", ["text"] = "Wirken in 5 sek.\nTools: Runenverzierte Silberrute\nReagenzien:\nVerbleite Phiole , Große Magieessenz , Seltsamer Staub (5)\nStellt Blackfathom-Manaöl her.\nBlackfathom-Manaöl\n25\nBenutzen: Stellt 5 Min. lang alle 5 Sek. 12 Mana wieder her und erhöht dabei den Zaubertrefferwert um 2%, wenn es auf eine Waffe angewendet wird. Dieser Effekt funktioniert nur in der Blackfathom-Tiefe.\n5 Aufladungen" }
