entries[431446] = { ["name"] = "Aufspießen", ["text"] = "Erhaltet die Fähigkeit 'Aufspießen':\n\nWenn Ihr ein Ziel mit 'Aufschlitzen', 'Prankenhieb' oder 'Zermalmen' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Zerfleischen (Bär)' abgeschlossen und 10 Wut erzeugt wird. Wenn Ihr ein Ziel mit 'Zerfleischen' (Katze) oder 'Schreddern' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Tigerfuror' abgeschlossen wird." }
entries[431447] = { ["name"] = "Helm prägen - Aufspießen", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Aufspießen':\n\nWenn Ihr ein Ziel mit 'Aufschlitzen', 'Prankenhieb' oder 'Zermalmen' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Zerfleischen (Bär)' abgeschlossen und 10 Wut erzeugt wird. Wenn Ihr ein Ziel mit 'Zerfleischen' (Katze) oder 'Schreddern' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Tigerfuror' abgeschlossen wird." }
